    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Index and length must be non-negative and index + length must not exceed string length");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            // Check for valid surrogate pair
            if (i + 1 < index + len && Character.isLowSurrogate(str.charAt(i + 1))) {
                size += 4; // Surrogate pair takes 4 bytes in UTF-8
                i++; // Skip the next character as it's part of the surrogate pair
            } else {
                size += 3; // Invalid surrogate pair, treat as separate characters
            }
        } else {
