    int i = 0;
    int size = lb.start;

    while (i < len) {
        final char c = str.charAt(i++);
        if (c < 0x80) {
            writeByte(lb, (byte) c, size++);
        } else if (c < 0x800) {
            writeByte(lb, (byte) (0xc0 | (c >> 6)), size++);
            writeByte(lb, (byte) (0x80 | (c & 0x3f)), size++);
        } else if (c >= 0xD800 && c <= 0xDFFF) {
            // Handle surrogate pairs
            if (i < len) {
                final char low = str.charAt(i++);
                if (c <= 0xDBFF && low >= 0xDC00 && low <= 0xDFFF) {
                    int codePoint = ((c & 0x3FF) << 10) + (low & 0x3FF) + 0x10000;
                    writeByte(lb, (byte) (0xf0 | (codePoint >> 18)), size++);
                    writeByte(lb, (byte) (0x80 | ((codePoint >> 12) & 0x3f)), size++);
                    writeByte(lb, (byte) (0x80 | ((codePoint >> 6) & 0x3f)), size++);
                    writeByte(lb, (byte) (0x80 | (codePoint & 0x3f)), size++);
